import pygame
from constants import *

class Mushroom:
    """蘑菇道具 - 吃后变大"""
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.w = 30
        self.h = 30
        self.vx = MUSHROOM_SPEED
        self.vy = 0
        self.alive = True
        self.emerging = True  # 从砖块中弹出
        self.emerge_y = y
        self.frame = 0

    def update(self, solids):
        if not self.alive:
            return

        # 弹出动画
        if self.emerging:
            self.y -= 1
            if self.y <= self.emerge_y - TILE:
                self.y = self.emerge_y - TILE
                self.emerging = False
            return

        # 重力
        self.vy += GRAVITY
        if self.vy > 10:
            self.vy = 10

        # 水平移动
        self.x += self.vx
        rect = pygame.Rect(self.x, self.y, self.w, self.h)
        for s in solids:
            if rect.colliderect(s):
                if self.vx > 0:
                    self.x = s.left - self.w
                elif self.vx < 0:
                    self.x = s.right
                self.vx = -self.vx
                rect = pygame.Rect(self.x, self.y, self.w, self.h)

        # 垂直移动
        self.y += self.vy
        rect = pygame.Rect(self.x, self.y, self.w, self.h)
        for s in solids:
            if rect.colliderect(s):
                if self.vy > 0:
                    self.y = s.top - self.h
                    self.vy = 0
                elif self.vy < 0:
                    self.y = s.bottom
                    self.vy = 0
                rect = pygame.Rect(self.x, self.y, self.w, self.h)

        # 掉落消失
        if self.y > SCREEN_H + 100:
            self.alive = False

        self.frame += 1

    def draw(self, surface, cam_x):
        if not self.alive:
            return
        sx = self.x - cam_x
        if sx < -self.w or sx > SCREEN_W + self.w:
            return

        # 蘑菇头（红色半圆）
        pygame.draw.ellipse(surface, RED, (sx, self.y, self.w, self.h * 2 // 3))
        # 白色斑点
        pygame.draw.circle(surface, WHITE, (sx + self.w // 3, self.y + self.h // 4), 4)
        pygame.draw.circle(surface, WHITE, (sx + 2 * self.w // 3, self.y + self.h // 4), 4)
        # 蘑菇柄
        pygame.draw.rect(surface, (240, 220, 180), (sx + 5, self.y + self.h // 2, self.w - 10, self.h // 2))
        # 眼睛
        pygame.draw.circle(surface, BLACK, (sx + self.w // 3, self.y + self.h * 2 // 3 + 2), 2)
        pygame.draw.circle(surface, BLACK, (sx + 2 * self.w // 3, self.y + self.h * 2 // 3 + 2), 2)

    def get_rect(self):
        return pygame.Rect(self.x, self.y, self.w, self.h)


class FireFlower:
    """火焰花道具 - 吃后可以发射火球"""
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.w = 28
        self.h = 30
        self.alive = True
        self.frame = 0
        self.collected = False

    def update(self):
        if not self.alive:
            return
        self.frame += 1

    def draw(self, surface, cam_x):
        if not self.alive or self.collected:
            return
        sx = self.x - cam_x
        if sx < -self.w or sx > SCREEN_W + self.w:
            return

        # 花茎
        pygame.draw.rect(surface, GREEN, (sx + self.w // 2 - 2, self.y + self.h // 2, 4, self.h // 2))
        # 叶子
        pygame.draw.ellipse(surface, DARK_GREEN, (sx + self.w // 2, self.y + self.h * 2 // 3, 12, 6))

        # 花瓣（旋转动画）
        petal_colors = [RED, YELLOW, RED, YELLOW]
        angle_offset = self.frame * 0.05
        for i, color in enumerate(petal_colors):
            angle = angle_offset + i * math.pi / 2
            px = sx + self.w // 2 + int(math.cos(angle) * 8)
            py = self.y + self.h // 3 + int(math.sin(angle) * 8)
            pygame.draw.circle(surface, color, (px, py), 6)

        # 花心
        pygame.draw.circle(surface, WHITE, (sx + self.w // 2, self.y + self.h // 3), 4)

    def get_rect(self):
        return pygame.Rect(self.x, self.y, self.w, self.h)


class Fireball:
    """火球"""
    def __init__(self, x, y, direction):
        self.x = x
        self.y = y
        self.w = 12
        self.h = 12
        self.vx = 7 * direction
        self.vy = 0
        self.alive = True
        self.frame = 0
        self.bounces = 0

    def update(self, solids):
        if not self.alive:
            return

        self.vy += GRAVITY * 0.5
        if self.vy > 8:
            self.vy = 8

        self.x += self.vx
        self.y += self.vy

        rect = pygame.Rect(self.x, self.y, self.w, self.h)
        for s in solids:
            if rect.colliderect(s):
                if self.vy > 0:
                    self.y = s.top - self.h
                    self.vy = -6  # 弹跳
                    self.bounces += 1
                elif self.vx > 0:
                    self.x = s.left - self.w
                    self.alive = False
                elif self.vx < 0:
                    self.x = s.right
                    self.alive = False
                rect = pygame.Rect(self.x, self.y, self.w, self.h)

        if self.bounces > 4 or self.y > SCREEN_H + 50:
            self.alive = False

        self.frame += 1

    def draw(self, surface, cam_x):
        if not self.alive:
            return
        sx = self.x - cam_x
        if sx < -self.w or sx > SCREEN_W + self.w:
            return

        # 火球
        size = 6 + int(abs(math.sin(self.frame * 0.3)) * 2)
        pygame.draw.circle(surface, (255, 100, 0), (int(sx + self.w // 2), int(self.y + self.h // 2)), size)
        pygame.draw.circle(surface, YELLOW, (int(sx + self.w // 2), int(self.y + self.h // 2)), size - 2)

    def get_rect(self):
        return pygame.Rect(self.x, self.y, self.w, self.h)


class Star:
    """无敌星道具"""
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.w = 28
        self.h = 28
        self.vx = MUSHROOM_SPEED
        self.vy = 0
        self.alive = True
        self.frame = 0

    def update(self, solids):
        if not self.alive:
            return

        self.vy += GRAVITY
        if self.vy > 10:
            self.vy = 10

        self.x += self.vx
        rect = pygame.Rect(self.x, self.y, self.w, self.h)
        for s in solids:
            if rect.colliderect(s):
                if self.vx > 0:
                    self.x = s.left - self.w
                elif self.vx < 0:
                    self.x = s.right
                self.vx = -self.vx
                rect = pygame.Rect(self.x, self.y, self.w, self.h)

        self.y += self.vy
        rect = pygame.Rect(self.x, self.y, self.w, self.h)
        for s in solids:
            if rect.colliderect(s):
                if self.vy > 0:
                    self.y = s.top - self.h
                    self.vy = 0
                elif self.vy < 0:
                    self.y = s.bottom
                    self.vy = 0
                rect = pygame.Rect(self.x, self.y, self.w, self.h)

        if self.y > SCREEN_H + 100:
            self.alive = False

        self.frame += 1

    def draw(self, surface, cam_x):
        if not self.alive:
            return
        sx = self.x - cam_x
        if sx < -self.w or sx > SCREEN_W + self.w:
            return

        # 旋转的五角星
        cx = sx + self.w // 2
        cy = self.y + self.h // 2
        angle = self.frame * 0.1
        color_cycle = [YELLOW, (255, 200, 0), (255, 150, 0), YELLOW]
        color = color_cycle[(self.frame // 8) % len(color_cycle)]

        points = []
        for i in range(5):
            a = angle + i * 2 * math.pi / 5 - math.pi / 2
            points.append((cx + int(math.cos(a) * 12), cy + int(math.sin(a) * 12)))
            a2 = a + math.pi / 5
            points.append((cx + int(math.cos(a2) * 5), cy + int(math.sin(a2) * 5)))

        pygame.draw.polygon(surface, color, points)
        pygame.draw.polygon(surface, WHITE, points, 1)

    def get_rect(self):
        return pygame.Rect(self.x, self.y, self.w, self.h)

